CREATE OR REPLACE FUNCTION public.can_manage_account_connections(_ws uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id JOIN public.user_profiles p ON p.user_id=m.user_id JOIN auth.users u ON u.id=m.user_id WHERE m.workspace_id=_ws AND m.user_id=auth.uid() AND m.role IN ('owner','admin') AND NOT m.is_contractor AND m.removed_at IS NULL AND w.status='active' AND NOT w.is_test_account AND p.status='active' AND NOT p.is_test_account AND p.deleted_at IS NULL AND u.email_confirmed_at IS NOT NULL AND lower(u.email)=lower(auth.jwt()->>'email')) $$;
CREATE OR REPLACE FUNCTION public.search_connection_businesses(_ws uuid,_mode text,_value text) RETURNS TABLE(workspace_id uuid,business_name text,mfn_id text,business_type text,location text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF NOT public.can_manage_account_connections(_ws) OR length(_value)<2 OR length(_value)>254 OR _mode NOT IN ('name','email','phone') THEN RAISE EXCEPTION 'Business search unavailable'; END IF;
 RETURN QUERY SELECT p.workspace_id,p.business_name,p.mfn_id,'provider'::text,array_to_string(p.cities,', ') FROM public.list_network_providers() p WHERE p.workspace_id<>_ws AND ((_mode='name' AND position(lower(_value) in lower(p.business_name))>0) OR (_mode='email' AND lower(trim(p.business_contact_email))=lower(trim(_value))) OR (_mode='phone' AND length(_value)=10 AND regexp_replace(regexp_replace(p.business_contact_phone,'[^0-9]','','g'),'^1([0-9]{10})$','\1')=_value)) ORDER BY p.business_name LIMIT 20; END $$;
CREATE FUNCTION public.audit_connection_invitation_delivery() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.delivery_status IS DISTINCT FROM OLD.delivery_status THEN INSERT INTO public.account_relationship_events(workspace_id,record_id,action,actor_id,person_mfn_id,workspace_mfn_id,details) VALUES(NEW.inviter_workspace_id,NEW.id,'invitation_delivery',NEW.created_by,NEW.person_mfn_id,NEW.workspace_mfn_id,jsonb_build_object('outcome',NEW.delivery_status,'generation',NEW.generation)); END IF; RETURN NEW; END $$;
CREATE TRIGGER connection_invitation_delivery_audit AFTER UPDATE OF delivery_status ON public.account_connection_invitations FOR EACH ROW EXECUTE FUNCTION public.audit_connection_invitation_delivery();